# semantic-mutant: SM-2D3D81E7
from __future__ import annotations

import json

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_CHAT_PATH = openai_chat_path()

_EXPECTED = {"item": "pallet jack", "quantity": 3}

_SCHEMA = {
    "type": "object",
    "properties": {
        "item": {"type": "string"},
        "quantity": {"type": "integer"},
    },
    "required": ["item", "quantity"],
    "additionalProperties": False,
}

_LIST_BODY = json.dumps([_EXPECTED])


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_one_item_list_reply_yields_plain_object_result(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A one-item list reply yields the same public object as a plain reply."""
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "inventory-assurance-value")
    reply = ScriptedResponse(
        status_code=200,
        headers={"Content-Type": "application/json"},
        body=openai_success_response(text=_LIST_BODY),
    )
    with (
        ScriptedHTTPServer(
            port=0,
            routes={("POST", _CHAT_PATH): [reply]},
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = LLMRouter(
            RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
            temperature=0.0,
        )
        response = router.query(
            "Count the pallet jacks visible on the shelf.",
            response_schema=_SCHEMA,
        )

    assert response.data["parsed"] == _EXPECTED
